package io.github.shellci.shell;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.List;

/** ShellCheck checks known to the plugin, generated by tools/gen_shellcheck_rules.py. */
public final class ShellCheckCatalog {

  private static final String RESOURCE = "/io/github/shellci/shell/shellcheck-rules.json";

  /**
   * @param wikiOnly documented in the ShellCheck wiki, no longer emitted by ShellCheck
   * @param legacy   defined by the former ShellCheck plugin for SonarQube only, no longer emitted by ShellCheck
   */
  public record Entry(String key, String name, String level, boolean wiki, boolean wikiOnly, boolean legacy, boolean defaultActive) {

    /** Kept so that existing issues and quality profiles keep their rule, but not raised by current ShellCheck releases. */
    public boolean retired() {
      return wikiOnly || legacy;
    }
  }

  private record Catalog(String shellcheckRevision, List<Entry> rules) {
  }

  private static final List<Entry> ENTRIES = load(RESOURCE);
  private static final java.util.Set<String> KEYS =
    ENTRIES.stream().map(Entry::key).collect(java.util.stream.Collectors.toUnmodifiableSet());

  private ShellCheckCatalog() {
  }

  public static List<Entry> entries() {
    return ENTRIES;
  }

  public static boolean contains(String ruleKey) {
    return KEYS.contains(ruleKey);
  }

  static List<Entry> load(String resource) {
    try (InputStream in = ShellCheckCatalog.class.getResourceAsStream(resource)) {
      if (in == null) {
        throw new IllegalStateException("Missing resource " + resource);
      }
      Catalog catalog = new Gson().fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), Catalog.class);
      return List.copyOf(catalog.rules());
    } catch (IOException e) {
      throw new UncheckedIOException(e);
    }
  }
}
